"""Checkpoint container: fixed binary snapshots for Sequential state.

A checkpoint fixes, in one self-describing document:

* every parameter tensor,
* every accumulated gradient (zeros when a parameter has none yet),
* the slice-boundary hidden state (when a forward is in flight),
* the layer order and per-layer parameter shapes,
* the engine bookkeeping a step needs (whether a backward is pending).

Wire format (all integers little-endian)::

    magic        8 bytes  b"SEQECKP1"
    version      uint32   format version
    header_len   uint64   length of the JSON header in bytes
    header       header_len bytes of UTF-8 JSON (shapes, layer order, flags)
    payload      header_len leaves, each a 1-byte tag ("i" | "f")
                 followed by int64 or float64
    end_magic    12 bytes b"SEQECKP1END"
    leaf_count   uint64   number of encoded leaves
    payload_crc  uint32   CRC-32 of header bytes followed by payload bytes

Float leaves are emitted as raw IEEE-754 bytes, so values (including NaN
payloads are impossible by construction -- non-finite values are rejected)
and the sign of negative zero round-trip bit for bit.

Loading validates the whole document before any state is handed back: any
truncation, corruption, version mismatch or structural problem rejects the
entire checkpoint with ValueError; nothing is silently filled in.
"""

from __future__ import annotations

import json
import math
import os
import struct
import tempfile
import zlib

MAGIC = b"SEQECKP1"
END_MAGIC = b"SEQECKP1END"
FORMAT_VERSION = 1

_TAG_INT = ord("i")
_TAG_FLOAT = ord("f")

_INT64_MIN = -(2**63)
_INT64_MAX = 2**63 - 1

_FIXED_OVERHEAD = len(MAGIC) + 4 + 8
_TRAILER_LEN = len(END_MAGIC) + 8 + 4

_TMP_PREFIX = ".seqckp.tmp-"


class CheckpointError(ValueError):
    """A checkpoint is missing, truncated, corrupt or structurally invalid."""


# ---------------------------------------------------------------------------
# Freezing / thawing: nested numeric trees <-> tagged binary leaves
# ---------------------------------------------------------------------------


def _check_leaf(value):
    if isinstance(value, bool):
        raise CheckpointError("checkpoint values must be numbers, not booleans")
    if isinstance(value, int):
        if not _INT64_MIN <= value <= _INT64_MAX:
            raise CheckpointError(
                "checkpoint contains an integer too large to represent (int64)"
            )
        return _TAG_INT
    if isinstance(value, float):
        if not math.isfinite(value):
            raise CheckpointError(
                "checkpoint contains a non-finite floating-point value"
            )
        return _TAG_FLOAT
    raise CheckpointError(
        f"checkpoint values must be numbers, got {type(value).__name__}"
    )


def _tree_shape(tree):
    shape = []
    node = tree
    while isinstance(node, list):
        shape.append(len(node))
        node = node[0]
    return shape


def _freeze_tree(tree, shape, payload):
    """Append *tree*'s leaves to *payload* and verify it matches *shape*."""
    if shape:
        if not isinstance(tree, list) or len(tree) != shape[0]:
            raise CheckpointError("checkpoint tensor tree does not match its shape")
        for item in tree:
            _freeze_tree(item, shape[1:], payload)
    else:
        if isinstance(tree, list):
            raise CheckpointError("checkpoint tensor tree does not match its shape")
        tag = _check_leaf(tree)
        if tag == _TAG_INT:
            payload.append(struct.pack("<bq", _TAG_INT, tree))
        else:
            payload.append(struct.pack("<bd", _TAG_FLOAT, tree))


def _freeze_entry(entry, payload):
    if not isinstance(entry, dict) or set(entry) != {"s", "v"}:
        raise CheckpointError("checkpoint tensor entry must be {'s', 'v'}")
    shape = entry["s"]
    _check_shape(shape)
    tree = entry["v"]
    if tree is None:
        if _shape_size(shape) != 0:
            raise CheckpointError("missing tensor values in checkpoint entry")
        return {"s": shape}
    actual = _tree_shape(tree)
    if actual != shape:
        raise CheckpointError("checkpoint tensor tree does not match its shape")
    _freeze_tree(tree, shape, payload)
    return {"s": shape}


def _shape_size(shape):
    size = 1
    for dim in shape:
        size *= dim
    return size


def _check_shape(shape):
    if not isinstance(shape, list) or not shape and shape != []:
        raise CheckportShapeError()
    for dim in shape:
        if not isinstance(dim, int) or isinstance(dim, bool) or dim <= 0:
            raise CheckpointError("checkpoint tensor shapes must be positive int lists")


class CheckportShapeError(CheckpointError):
    pass


def _zeros_tree(shape):
    if not shape:
        return 0.0
    return [_zeros_tree(shape[1:]) for _ in range(shape[0])]


# ---------------------------------------------------------------------------
# Encoding
# ---------------------------------------------------------------------------


def _freeze(document, payload):
    """Turn a snapshot document into a JSON-safe header, appending leaves."""
    if not isinstance(document, dict):
        raise CheckpointError("checkpoint document must be an object")
    header = {}

    entries = document.get("params")
    if not isinstance(entries, list) or not entries:
        raise CheckpointError("checkpoint must record at least one parameter tensor")
    header["params"] = [_freeze_entry(entry, payload) for entry in entries]

    grads = document.get("grads")
    if not isinstance(grads, list) or len(grads) != len(entries):
        raise CheckpointError("checkpoint must record one gradient slot per parameter")
    frozen_grads = []
    for entry in grads:
        if entry is None:
            raise CheckpointError("every gradient must be written (use zeros)")
        frozen_grads.append(_freeze_entry(entry, payload))
    header["grads"] = frozen_grads

    hidden = document.get("hidden")
    if hidden is not None:
        if not isinstance(hidden, list) or not hidden:
            raise CheckpointError("hidden state must be a non-empty list or null")
        header["hidden"] = [_freeze_entry(entry, payload) for entry in hidden]
    else:
        header["hidden"] = None

    layers = document.get("layers")
    if not isinstance(layers, list) or len(layers) == 0:
        raise CheckpointError("checkpoint must record the layer order")
    header["layers"] = [_freeze_layer(layer) for layer in layers]
    if sum(layer["n"] for layer in header["layers"]) != len(entries):
        raise CheckpointError("layer parameter counts do not match the parameter list")

    pending = document.get("pending")
    if not isinstance(pending, bool):
        raise CheckpointError("checkpoint pending flag must be a boolean")
    header["pending"] = pending
    header["v"] = FORMAT_VERSION
    return header


def _freeze_layer(layer):
    if not isinstance(layer, dict) or set(layer) != {"kind", "shapes"}:
        raise CheckpointError("layer descriptor must be {'kind', 'shapes'}")
    kind = layer["kind"]
    if not isinstance(kind, str) or not kind:
        raise CheckpointError("layer kind must be a non-empty string")
    shapes = layer["shapes"]
    if not isinstance(shapes, list) or not shapes:
        raise CheckpointError("each layer must record at least one parameter shape")
    for shape in shapes:
        _check_shape(shape)
    return {"kind": kind, "shapes": [list(shape) for shape in shapes]}


def build_bytes(document):
    """Serialize a snapshot document to the fixed binary representation."""
    payload = []
    header = _freeze(document, payload)
    header_bytes = json.dumps(
        header, ensure_ascii=False, separators=(",", ":"), sort_keys=True
    ).encode("utf-8")

    body = bytearray()
    body += MAGIC
    body += struct.pack("<I", FORMAT_VERSION)
    body += struct.pack("<Q", len(header_bytes))
    body += header_bytes
    crc = zlib.crc32(header_bytes)
    for chunk in payload:
        body += chunk
        crc = zlib.crc32(chunk, crc)
    leaf_count = sum(len(chunk) == 9 and chunk[0] == _TAG_INT or
                     len(chunk) == 9 and chunk[0] == _TAG_FLOAT
                     for chunk in payload)
    body += END_MAGIC
    body += struct.pack("<Q", leaf_count)
    body += struct.pack("<I", crc & 0xFFFFFFFF)
    return bytes(body)

